// Exact finite alphabet-bank q13 receiver; six unsupported long words allowed.
// Seven disjoint F-free pairs cover every qualifying action. No short group
// participates in key generation or fit. Native-word and red-rubric alphabets.
#include <bits/stdc++.h>
#include <codecvt>
#include <locale>
using namespace std;
using u64=uint64_t;using A=array<int,29>;using K=array<int,13>;
const string sym="0123456789abcdefghijklmnopqrs";
const u32string runes=U"ᚠᚢᚦᚩᚱᚳᚷᚹᚻᚾᛁᛄᛇᛈᛉᛋᛏᛒᛖᛗᛚᛝᛟᛞᚪᚫᚣᛡᛠ";
const vector<string> names={"F","U","TH","O","R","C","G","W","H","N","I","J","EO","P","X","S","T","B","E","M","L","NG","OE","D","A","AE","Y","IA","EA"};
int md(int x){return (x%29+29)%29;}
string file(const string&p){ifstream f(p);if(!f)throw runtime_error(p);return string(istreambuf_iterator<char>(f),{});}
vector<string> words(const string&s){istringstream f(s);vector<string> v;string w;while(f>>w)v.push_back(w);return v;}
vector<string> fields(const string&s,const string&k){regex re("\""+k+"\"\\s*:\\s*\"([^\"]*)\"");vector<string> v;for(sregex_iterator i(s.begin(),s.end(),re),e;i!=e;++i)v.push_back((*i)[1]);return v;}
set<string> D;vector<string> by[64],nof[64];unordered_set<string> lookup;
void spell(const string&s,int i,string w){if(i==(int)s.size()){D.insert(w);return;}for(int n=1;n<=3&&i+n<=(int)s.size();n++){auto t=s.substr(i,n);int j=-1;if(n==3){if(t=="ING")j=21;}else for(int x=0;x<29;x++)if(t==names[x]){j=x;break;}if(j>=0)spell(s,i+n,w+sym[j]);}}
void dictionary(){istringstream f(file("resources/control/english_wordfreq_textblob.txt"));string l;regex re("^([a-z]+)\\s+([0-9]+)$");smatch m;while(getline(f,l)){if(!regex_match(l,m,re))continue;string s=m[1],v,z;for(char c:s)v+=toupper(c);for(int i=0;i<(int)v.size();i++){if(v.substr(i,2)=="QU"){z+="CW";i++;continue;}char c=v[i];z+=c=='V'?'U':c=='K'||c=='Q'?'C':c=='Z'?'S':c;}spell(z,0,"");}if(D.size()!=38910)throw runtime_error("dictionary base");for(auto&w:words(fields(file("im-results/lp2-shared-gp29-q8-terminal-corrected-fixtures.json"),"added").at(0)))D.insert(w);if(D.size()!=38938)throw runtime_error("dictionary expanded");for(auto&w:D){lookup.insert(w);if(w.size()<64){by[w.size()].push_back(w);if(w.find('0')==string::npos)nof[w.size()].push_back(w);}}}
vector<string> runeGroups(const string&s){wstring_convert<codecvt_utf8<char32_t>,char32_t> cv;auto u=cv.from_bytes(s);vector<string> v;string w;for(auto c:u){size_t i=runes.find(c);if(i!=u32string::npos)w+=sym[i];else if(!w.empty()){v.push_back(w);w.clear();}}if(!w.empty())v.push_back(w);return v;}
vector<string> chapter(){auto s=file("resources/transcriptions/lp2-image-corrected.txt");wstring_convert<codecvt_utf8<char32_t>,char32_t> cv;auto u=cv.from_bytes(s);int pg=0;vector<string> v;string w;for(auto c:u){if(c==U'%'){pg++;continue;}if(pg<40||pg>=53)continue;if(c==U'/'||c==U'\n'||c==U'\r'||c==U' '||c==U'\t')continue;size_t i=runes.find(c);if(i!=u32string::npos)w+=sym[i];else if(!w.empty()){v.push_back(w);w.clear();}}if(!w.empty())v.push_back(w);int n=0;for(auto&x:v)n+=x.size();if(v.size()!=669||n!=3008)throw runtime_error("chapter shape");return v;}
vector<A> bank;vector<string> labels;
void alphabets(){auto s=file("resources/external/relikd-solved-gp29-native-v1.json");auto v=runeGroups(s.substr(s.find("\"sections\"")));set<string> pool(v.begin(),v.end());if(pool.size()!=272)throw runtime_error("native pool "+to_string(pool.size()));vector<string> pp(pool.begin(),pool.end());pp.push_back("jlnr2eaj");pp.push_back("ojlnr2eaj");set<A> seen;for(auto&w:pp)for(int f=0;f<2;f++){string order;if(f)order+='0';for(char c:w+sym)if(order.find(c)==string::npos)order+=c;A a{},id{};int z=order.find('0');for(int i=0;i<29;i++)a[i]=md((int)order.find(sym[i])-z);int scale=1;while(a[1]*scale%29!=1)scale++;for(int i=0;i<29;i++)id[i]=a[i]*scale%29;if(seen.insert(id).second){bank.push_back(a);labels.push_back(w+(f?":F-first":":rotate"));}}if(bank.size()!=527)throw runtime_error("bank size "+to_string(bank.size()));}
string encrypt(const string&w,const A&p,const K&k,int j){A ip{};for(int i=0;i<29;i++)ip[p[i]]=i;string c;for(char x:w){int z=sym.find(x);if(!z)c+='0';else{c+=sym[ip[md(p[z]+k[j])]];j=(j+1)%13;}}return c;}
bool support(const string&c,const A&p,const K&k,const string*truth=nullptr){A ip{};for(int i=0;i<29;i++)ip[p[i]]=i;int mp[13][29];for(int j=0;j<13;j++)for(int x=0;x<29;x++)mp[j][x]=ip[md(p[x]-k[j])];string w(c.size(),'0');function<bool(int,int)> rec=[&](int i,int j){if(i==(int)c.size())return truth?w==*truth:lookup.count(w)>0;int x=sym.find(c[i]);if(x==0){w[i]='0';if(rec(i+1,j))return true;}int y=mp[j][x];if(!y)return false;w[i]=sym[y];return rec(i+1,(j+1)%13);};for(int j=0;j<13;j++)if(rec(0,j))return true;return false;}
K norm(K k){K a=k;for(int i=1;i<13;i++){rotate(k.begin(),k.begin()+1,k.end());a=min(a,k);}return a;}
vector<K> opts(const string&c,const A&p){if(c.find('0')!=string::npos)throw runtime_error("F in anchor");vector<K> v;for(auto&w:nof[c.size()]){K k;k.fill(-1);bool ok=true;for(int i=0;i<(int)c.size();i++){int d=md(p[sym.find(c[i])]-p[sym.find(w[i])]);if(k[i%13]>=0&&k[i%13]!=d){ok=false;break;}k[i%13]=d;}if(ok)v.push_back(k);}return v;}
template<class T> string ar(const T&v){string s="[";for(auto x:v){if(s.size()>1)s+=",";s+=to_string(x);}return s+"]";}
struct Fit{int bankid,support;K key;};struct Stats{u64 joins=0,keys=0,duplicates=0,options=0;int best=0;vector<Fit> fits;};
Stats recover(const vector<string>&C,const vector<pair<int,int>>&pairs){Stats out;for(int b=0;b<(int)bank.size();b++){auto&p=bank[b];set<K> seen;for(auto [a,z]:pairs){auto A1=opts(C[a],p),A2=opts(C[z],p);out.options+=A1.size()+A2.size();for(int phase=0;phase<13;phase++){vector<pair<int,int>> overlap;for(int j=0;j<min(13,(int)C[z].size());j++){int x=(j+phase)%13;if(x<min(13,(int)C[a].size()))overlap.push_back({x,j});}if(overlap.size()<7)throw runtime_error("overlap");unordered_multimap<u64,int> index;index.reserve(A1.size()*2+1);for(int i=0;i<(int)A1.size();i++){u64 h=0;for(auto [x,j]:overlap)h=h*29+A1[i][x];index.emplace(h,i);}for(auto&k2:A2){u64 h=0;for(auto [x,j]:overlap)h=h*29+k2[j];auto range=index.equal_range(h);for(auto it=range.first;it!=range.second;++it){out.joins++;K k=A1[it->second];for(int j=0;j<13;j++)if(k2[j]>=0){int x=(j+phase)%13;if(k[x]>=0&&k[x]!=k2[j])throw runtime_error("hash collision");k[x]=k2[j];}vector<int> missing;for(int j=0;j<13;j++)if(k[j]<0)missing.push_back(j);if(missing.size()>3)throw runtime_error("key dimension");function<void(int)> fill=[&](int m){if(m<(int)missing.size()){for(int x=0;x<29;x++){k[missing[m]]=x;fill(m+1);}return;}if(all_of(k.begin(),k.end(),[&](int x){return x==k[0];}))return;K n=norm(k);if(!seen.insert(n).second){out.duplicates++;return;}out.keys++;int yes=0,no=0;for(auto&c:C){if(support(c,p,n))yes++;else if(++no>6)break;}out.best=max(out.best,yes);if(no<=6&&yes+no==(int)C.size()){out.fits.push_back({b,yes,n});cout<<"FIT "<<b<<" "<<yes<<" "<<ar(n)<<endl;}};fill(0);}}}}}return out;}
int main(int argc,char**argv){dictionary();alphabets();string mode=argc>1?argv[1]:"0";bool control=mode!="original";auto f=file("im-results/lp2-shared-gp29-q8-affine-long-fixtures.json");auto original=words(fields(f,"originalTrain").at(0));if(original.size()!=24)throw runtime_error("anchors");vector<int> elig;for(int i=0;i<24;i++)if(original[i].find('0')==string::npos)elig.push_back(i);if(elig.size()!=15)throw runtime_error("F-free anchors");vector<pair<int,int>> pairs;for(int i=0;i<7;i++)pairs.push_back({elig[i],elig[13-i]});vector<string>C=original,H,T,HT;A truthP{};K truthK{};int truthB=-1;vector<int> omit;
if(control){int i=stoi(mode);if(i<0||i>1)throw runtime_error("control");auto tt=words(fields(f,"truth").at(i));T.assign(tt.begin(),tt.begin()+24);HT.assign(tt.begin()+24,tt.end());mt19937 rng(0x29f01377u+i);truthB=i==0?17:(int)bank.size()-2;truthP=bank[truthB];for(int j=0;j<13;j++)truthK[j]=rng()%29;for(int j=0;j<6;j++)omit.push_back(j%2?pairs[j].second:pairs[j].first);
for(int j=0;j<24;j++){bool zeroFree=find(elig.begin(),elig.end(),j)!=elig.end(),bad=find(omit.begin(),omit.end(),j)!=omit.end();bool ok=false;for(int attempt=0;attempt<100000&&!ok;attempt++){if(bad){T[j].clear();for(int x=0;x<(int)original[j].size();x++)T[j]+=sym[1+rng()%28];}else if(attempt>0||!lookup.count(T[j])||(zeroFree&&T[j].find('0')!=string::npos)){auto&v=zeroFree?nof[original[j].size()]:by[original[j].size()];T[j]=v[rng()%v.size()];}C[j]=encrypt(T[j],truthP,truthK,rng()%13);ok=(!zeroFree||C[j].find('0')==string::npos)&&(!bad||!support(C[j],truthP,truthK));}if(!ok)throw runtime_error("plant generation");}
for(auto&w:HT)H.push_back(encrypt(w,truthP,truthK,rng()%13));}
else{auto v=chapter();vector<string>L;for(auto&w:v)(w.size()>=10?L:H).push_back(w);auto a=original;sort(a.begin(),a.end());sort(L.begin(),L.end());if(a!=L)throw runtime_error("original profile");}
auto R=recover(C,pairs);bool exact=false;int trueTrain=0,trueHeld=0;ostringstream o;o<<"{\"mode\":\""<<mode<<"\",\"q\":13,\"dictionary\":"<<D.size()<<",\"bank\":"<<bank.size()<<",\"budget\":6,\"pair_joins\":"<<R.joins<<",\"full_keys\":"<<R.keys<<",\"duplicates\":"<<R.duplicates<<",\"option_incidences\":"<<R.options<<",\"holdout_count\":"<<H.size()<<",\"fits\":[";
for(size_t i=0;i<R.fits.size();i++){auto&x=R.fits[i];auto&p=bank[x.bankid];int held=0;for(auto&w:H)held+=support(w,p,x.key);if(i)o<<",";o<<"{\"alphabet\":"<<x.bankid<<",\"label\":\""<<labels[x.bankid]<<"\",\"pi\":"<<ar(p)<<",\"key\":"<<ar(x.key)<<",\"train\":"<<x.support<<",\"holdout\":"<<held<<"}";if(control&&x.bankid==truthB&&x.key==norm(truthK)){exact=true;for(int j=0;j<24;j++)trueTrain+=support(C[j],p,x.key,&T[j]);for(int j=0;j<(int)H.size();j++)trueHeld+=support(H[j],p,x.key,&HT[j]);}}
o<<"],\"exact\":"<<(exact?"true":"false")<<",\"train_truth\":"<<trueTrain<<",\"holdout_truth\":"<<trueHeld<<",\"omitted\":"<<ar(omit)<<"}";cout<<"FINAL "<<o.str()<<endl;if(const char*p=getenv("SFT_OUTPUT")){ofstream f(p);f<<o.str()<<endl;}return 0;}
